function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 13) return 'nums needs 1 to 13 values.';
  if (nums.some(v => v < 1 || v > 100000)) return 'Each value in nums is between 1 and 10^5.';
  if (k < 1 || k > 100) return 'k is between 1 and 100.';
  return null;
}

