function concatenatedDivisibility(nums, k) {
  const sorted = [...nums].sort((a, b) => a - b);
  const n = sorted.length;
  const full = (1 << n) - 1;
  const shift = sorted.map(value => 10 ** String(value).length % k);
  const canFinish = new Uint8Array((full + 1) * k);
  canFinish[full * k] = 1;
  for (let mask = full - 1; mask >= 0; mask--) {
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        continue;
      }
      const next = (mask | (1 << i)) * k;
      const factor = shift[i];
      const value = sorted[i];
      for (let rem = 0; rem < k; rem++) {
        if (canFinish[next + (rem * factor + value) % k]) {
          canFinish[mask * k + rem] = 1;
        }
      }
    }
  }
  if (!canFinish[0]) {
    return [];
  }
  const order = [];
  let used = 0;
  let remainder = 0;
  while (used !== full) {
    for (let i = 0; i < n; i++) {
      const after = (remainder * shift[i] + sorted[i]) % k;
      if (!(used & (1 << i)) && canFinish[(used | (1 << i)) * k + after]) {
        order.push(sorted[i]);
        used |= 1 << i;
        remainder = after;
        break;
      }
    }
  }
  return order;
}

