function concatenatedDivisibility(nums, k) {
  // Walk through the orders in increasing lexicographic order; the first divisible one is the answer.
  const order = [...nums].sort((a, b) => a - b);
  for (;;) {
    let remainder = 0;
    for (const digit of order.join('')) remainder = (remainder * 10 + Number(digit)) % k;
    if (remainder === 0) return order;
    // Step to the next permutation (equal values are never swapped, so each order appears once).
    let i = order.length - 2;
    while (i >= 0 && order[i] >= order[i + 1]) i--;
    if (i < 0) return [];
    let j = order.length - 1;
    while (order[j] <= order[i]) j--;
    [order[i], order[j]] = [order[j], order[i]];
    const tail = order.splice(i + 1).reverse();
    order.push(...tail);
  }
}

