function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const n = size === 'large' ? 13 : 1 + Math.floor(rand() * 7);
  // Short and long numbers, so the digit counts (and the shifts) differ.
  const top = pick([9, 99, 1000, 100000]);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Small divisors usually have answers; multiples of 2 and 5 depend on the last digits; large ones often have none.
  const k = pick([1 + Math.floor(rand() * 12), 1 + Math.floor(rand() * 100), pick([10, 25, 50, 100])]);
  if (rand() < 0.5) {
    // Plant an answer: replace the last number by a 3- to 5-digit one that makes the current order divisible.
    let prefix = 0;
    for (const digit of nums.slice(0, -1).join('')) prefix = (prefix * 10 + Number(digit)) % k;
    const digits = 3 + Math.floor(rand() * 3);
    const low = 10 ** (digits - 1);
    const target = (k - prefix * (10 ** digits % k) % k) % k;
    nums[n - 1] = low + ((target - low % k) % k + k) % k;
  }
  return [nums, k];
}
